def eq(a,b):
    if isinstance(a,dict):
        assert type(b)==dict and a.keys()==b.keys(),(a,b)
        for k in a:eq(a[k],b[k])
    elif isinstance(a,list):
        assert isinstance(b,list) and len(a)==len(b),(a,b)
        for x,y in zip(a,b):eq(x,y)
    elif a is None or isinstance(a,(str,bool,int)):
        assert type(a)==type(b) and a==b,(a,b)
    else:
        assert type(b) in (int,float) and math.isfinite(b) and close(a,b)<=1,(a,b)

def run(case):
    validate({'cases':[case]})
    output=run_case(case)['events']
    W=len(case['workers']);E=len(case['edges']);K=len(case['commodities'])
    g=0;seq=0;tickets={};receipts=set();saves={}
    st={'c':[e[2] for e in case['edges']], 'd':[k['demand'] for k in case['commodities']], 'p':[copy.deepcopy(k['paths']) for k in case['commodities']], 'rho':case['rho'],'mode':case['mode']}
    def reset():
        st.update(r=0, z=[0.]*E, u=[0.]*E,A=[[0.]*E for w in range(W)],flow=[[0.]*len(p) for p in st['p']],seen=set(),fresh=set(),last=[None]*W,latest=[None]*W)
    def load():return [sum(st['A'][w][e] for w in range(W)) for e in range(E)]
    reset()
    for ev,res in zip(case['events'],output):
        op=ev['op']
        if op=='configure':
            for e,c in ev['capacity']:st['c'][e]=c
            for k,d in ev['demand']:st['d'][k]=d
            for k,p,path in ev['paths']:st['p'][k][p]=copy.deepcopy(path)
            st['mode']=ev['mode'];g+=1;reset()
            eq({'op':op,'generation':g},res)
        elif op=='issue':
            w=ev['worker'];s=load();c=st['c']
            B=[st['A'][w][e]/c[e]+(st['z'][e]-s[e]/c[e]-st['u'][e])/W if c[e] else 0. for e in range(E)]
            prop=res['result'];verify(case['workers'][w],np.array(c),st['d'],st['p'],st['mode'],st['rho'],B,prop)
            eq({'op':op,'id':ev['id'],'worker':w,'generation':g,'bias':B,'rho':st['rho'],'result':prop},res)
            tickets[ev['id']]=(g,seq,w,copy.deepcopy(prop));seq+=1
        elif op=='deliver':
            ticket=ev['id'];tg,tseq,w,prop=tickets[ticket]
            if ticket in receipts: status='duplicate'
            elif tg!=g:status='obsolete'
            elif st['latest'][w] is not None and tseq<st['latest'][w]:status='superseded'
            elif prop['status']=='infeasible':status='infeasible'
            else:
                status='accepted';st['latest'][w]=tseq;st['seen'].add(w);st['fresh'].add(w);st['last'][w]=st['r']
                st['A'][w]=prop['edge_load'].copy()
                for k,flow in zip(case['workers'][w],prop['flow']):st['flow'][k]=flow.copy()
            receipts.add(ticket)
            eq({'op':op,'id':ticket,'status':status},res)
        elif op=='retune':
            st['u']=[u*st['rho']/ev['rho'] for u in st['u']];st['rho']=ev['rho']
            eq({'op':op,'rho':st['rho']},res)
        elif op=='save':
            saves[ev['name']]=copy.deepcopy(st);eq({'op':op,'name':ev['name']},res)
        elif op=='restore':
            st=copy.deepcopy(saves[ev['name']]);g+=1
            eq({'op':op,'name':ev['name'],'generation':g},res)
        elif op=='step':
            missing=sorted(set(range(W))-st['seen'])
            stale=sorted(w for w in st['seen'] if st['r']-st['last'][w]>case['max_lag'])
            if missing or stale or len(st['fresh'])<case['quorum']:
                eq({'op':op,'status':'waiting','missing':missing,'stale':stale,'fresh':sorted(st['fresh'])},res)
            else:
                s=load();c=st['c'];alpha=case['relax'][0]/case['relax'][1]
                v=[alpha*s[e]/c[e]+(1-alpha)*st['z'][e]+st['u'][e] if c[e] else 0. for e in range(E)]
                z=res['z'];u=res['dual'];p=res['pressure'];h=res['ceiling']
                assert h>=0
                assert all(t>=0 for t in p)
                if st['mode']=='admit':eq(1.,h)
                else:
                    assert sum(p)<=1+2e-7
                    assert close(h*(1-sum(p)),0)<=1,('hp',h,sum(p))
                for e in range(E):
                    if c[e]:
                        assert z[e]<=h+1e-7+1e-7*max(abs(h),abs(z[e]))
                        assert close(st['rho']*(z[e]-v[e])+p[e],0)<=1
                        assert close(p[e]*(h-z[e]),0)<=1
                        assert close(u[e],v[e]-z[e])<=1
                    else: assert z[e]==u[e]==p[e]==0
                st['r']+=1;st['fresh'].clear();st['z']=z.copy();st['u']=u.copy()
                eq({'op':op,'status':'advanced','round':st['r'],'load':s,'z':z,'dual':u,'pressure':p,'ceiling':h},res)
        elif op=='audit':
            eq({'op':op,'generation':g,'round':st['r'],'rho':st['rho'],'flow':st['flow'],'worker_load':st['A'],'load':load(),'z':st['z'],'dual':st['u'],'seen':sorted(st['seen']),'fresh':sorted(st['fresh']),'age':[st['r']-st['last'][w] if w in st['seen'] else None for w in range(W)]},res)
    return output

def create():
    n=random.randint(2,12)
    pairs=list(itertools.permutations(range(n),2));random.shuffle(pairs)
    pairs=pairs[:random.randint(1,min(len(pairs),64))]
    edges=[[a,b,random.choice([0,1,2,10,100,1000])] for a,b in pairs]
    lookup={tuple(e[:2]):i for i,e in enumerate(edges)}
    commodities=[]; choices=[];left=96
    for k in range(random.randint(0,24)):
        s,t=random.sample(range(n),2)
        paths=set()
        if (s,t) in lookup:paths.add((lookup[s,t],))
        for _ in range(20):
            length=random.randint(0,min(n-2,11))
            nodes=[s]+random.sample([u for u in range(n) if u not in (s,t)],length)+[t]
            if all((a,b) in lookup for a,b in zip(nodes,nodes[1:])):
                paths.add(tuple(lookup[a,b] for a,b in zip(nodes,nodes[1:])))
        paths=[list(p) for p in paths]
        choices.append(paths)
        p=paths[:random.randint(0,min(len(paths),min(8,left)))]
        if len(p)<min(8,left):p += [None]*random.randint(0,min(8,left)-len(p))
        left-=len(p)
        commodities.append({'source':s,'sink':t,'demand':random.choice([0,1,10,1000]),'paths':p})
    K=len(commodities);W=random.randint(1,8)
    workers=[[] for w in range(W)]
    for k in range(K):workers[random.randrange(W)].append(k)
    case={'nodes':n,'edges':edges,'commodities':commodities,'workers':workers,'quorum':random.randint(1,W),'max_lag':random.randint(0,4),'relax':random.choice([[1,1],[2,2],[3,2],[15,8]]),'rho':random.randint(1,8),'mode':random.choice(['route','admit']),'events':[]}
    tickets=[];saves={};pstate=copy.deepcopy([c['paths'] for c in commodities]);issuecount=0
    for j in range(256):
        ops=['audit','retune','save','configure','step','step','step','issue','issue','deliver']
        op=random.choice(ops)
        if random.random()<.07 and saves:op='restore'
        if op=='issue':
            if issuecount==48:op='step'
            else:
                ticket=random.randrange(10**9);tickets.append(ticket);issuecount+=1
                ev={'op':op,'id':ticket,'worker':random.randrange(W)}
        if op=='deliver':
            if tickets:ev={'op':op,'id':random.choice(tickets)}
            else:op='step'
        if op in ('audit','step'):ev={'op':op}
        elif op=='retune':ev={'op':op,'rho':random.randint(1,8)}
        elif op=='save':
            name=j;saves[name]=copy.deepcopy(pstate);ev={'op':op,'name':name}
        elif op=='restore':
            name=random.choice(list(saves));pstate=copy.deepcopy(saves[name]);ev={'op':op,'name':name}
        elif op=='configure':
            capacities=[[e,random.choice([0,1,2,1000])] for e in range(len(edges)) if random.random()<.1]
            demands=[[k,random.choice([0,1,1000])] for k in range(K) if random.random()<.1]
            change=[]
            for k in range(K):
                if random.random()<.1:
                    opts=copy.deepcopy(choices[k]);random.shuffle(opts);row=[]
                    for p in range(len(pstate[k])):
                        path=opts.pop() if opts and random.random()<.8 else None
                        row.append(path)
                        change.append([k,p,path])
                    pstate[k]=row
            ev={'op':op,'mode':random.choice(['route','admit']),'capacity':capacities,'demand':demands,'paths':change}
        case['events'].append(ev)
    return case

